- goal_key() -> Num  [Z169b] a number that changes whenever the goal set changes: bag state, locked altars, living groups
- shop_value(o: Option) -> Num  [Z169c] shop: a durability health emblem, then a jungle health emblem, then power strength; bigger buys first
- cast_v2(o: Option) -> Num  [Z169d] value of a cast: damage or stun on foes and camps, shield or heal when hurt, attack resets once the attack is spent, dash two steps toward the goal; calls progress
- pick_value(c: Num) -> Num  [Z15a] draft preference: Vendetta, Vesper Vale, Tavi, Ryth, Ren, then anything
- retreat_value(o: Option) -> Num  [Z169f] while retreating: step or dash home first, shield or heal, otherwise hit only what is in reach; calls cast_v2, raw_gain
- raw_gain(t: Tile) -> Num  [Z169g] how much closer a step onto t brings me on this turn's walking field (no danger penalty); calls goal_field
- consider(k: Num) -> Bool  [Z169h] option kinds worth listing this pass: skip kinds never used, casts with no slot ready, shopping off spawn, tributes without gems
- big_camp(u: Unit) -> Bool  [Z169i] a monolith or golem camp

## EDITABLE gene score (called by the fixed loop)
```python
@gene('s1', 'value of doing this option now: draft, casts, focus the weakest foe, fight back against awake camps, heal on spawn, cash out a big bag; shop durability and jungle emblems; recall only out of danger')
def score(o: Option) -> Num:
    if o.kind == PICK:
        return pick_value(o.champ)
    if o.kind == BUY:
        return shop_value(o)
    if o.kind == RECALL:
        if under_threat():
            return 0
        if me().health_frac < 0.35:
            return 76
        return 76 if gems() >= 10 and me().health_frac < 0.5 and count_units(enemies()) == 0 else 0
    if RETREAT and (o.kind == MOVE or o.kind == CAST or o.kind == ATTACK):
        return retreat_value(o)
    if o.kind == CAST:
        return cast_v2(o)
    if o.kind == ATTACK:
        if o.unit.is_champion:
            return 80 + 10 * (0.6312 - o.unit.health_frac)
        if gems() == 0:
            if big_camp(o.unit) and not is_awake(o.unit):
                return 0
            return 60 + 5 * (1 - o.unit.health_frac)
        if is_awake(o.unit):
            return 55
        return 54 if path_blocked() else 0
    if o.kind == TRIBUTE:
        return 70
    if o.kind == MOVE:
        if me().pos in my_spawn() and me().health_frac < 0.9 and count_units(enemies()) == 0:
            return 0
        return 50 if progress(o.tile) > 0 else 0
    return 0
```

## EDITABLE gene under_threat (called by score, update)
```python
@gene('Z61a', 'an enemy champion within 5 or an awake camp within its range + 1', parents=['s3'])
def under_threat() -> Bool:
    p = me().pos
    return any(dist(p, u.pos) <= 5 for u in enemies()) or any(is_awake(c) and dist(p, c.pos) <= c.attack_range + 1 for c in camps())
```

